SELECT account.id AS user_id, account.username, account.name, account.dept_id, account.status
FROM sys_user account
WHERE account.deleted = 0

    AND account.username LIKE CONCAT('%', #{query.username}, '%')


    AND account.name LIKE CONCAT('%', #{query.name}, '%')


    AND account.dept_id = #{query.deptId}


    AND account.status = #{query.status}

AND EXISTS (
    SELECT 1 FROM sys_user_post user_post
    WHERE user_post.user_id = account.id AND user_post.post_id = #{query.postId}
)
ORDER BY account.id

SELECT account.id FROM sys_user account WHERE account.deleted = 0 AND account.dept_id IN
#{departmentId}
UNION SELECT account.id FROM sys_post post INNER JOIN sys_user_post user_post ON user_post.post_id = post.id INNER JOIN sys_user account ON account.id = user_post.user_id AND account.deleted = 0 WHERE post.deleted = 0 AND post.status = 0 AND post.dept_id IN
#{departmentId}
UNION SELECT account.id FROM sys_role_dept role_dept INNER JOIN sys_role role ON role.id = role_dept.role_id AND role.deleted = 0 AND role.status = 0 AND role.data_scope = 2 INNER JOIN sys_user_role user_role ON user_role.role_id = role.id INNER JOIN sys_user account ON account.id = user_role.user_id AND account.deleted = 0 WHERE role_dept.dept_id IN
#{departmentId}

SELECT role_id, dept_id FROM sys_role_dept
WHERE role_id IN

    #{roleId}
